fn gcd_calc(m: u32, n: u32) -> u32 {
    debug_assert!(m > 0 && n > 0);

    // Euclidean algorithm via repeated remainder.
    // Invariant: gcd(a, b) == gcd(m, n) and a > 0, b > 0.
    let mut a = m;
    let mut b = n;

    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }

    // Since inputs are strictly positive, the final gcd is also strictly positive.
    a
}